                { name = "Smart", body = "#showtooltip Misdirection\n/click TankMDButton1", icon = 134400, desc = "Misdirection WeakAura/AddOn This automatically MD's your tank in the group with no need for targeting or focusing or anything. Install the AddOn, set up the macro, and you're golden. Grab this AddOn . Set up this Macro: Done (do not forget to put it on your bars)!" },
                { name = "Command Pet — Fortitude of the Bear", body = "#showtooltip\n/target [@mouseover,help,nodead]\n/use Master's Call(Cunning Ability)\n/targetlasttarget\n/use Fortitude of the Bear", icon = 134400, desc = "Fortitude of the Bear Master's Call Macro Master's Call mouseover macros seem really buggy. This macro has a workaround for mouseover Master's Call . If you have a Tenacity pet out, it will use Fortitude of the Bear . If you want, you can add /use Primal Rage to it at the bottom if you want it to Lust with a Ferocity pet out, I personally dislike that due to risks of accidentally Lusting." },
                { name = "Focus Mouseover Macro", body = "/focus [@mouseover,exists,harm,nodead][]\n/run if not GetRaidTargetIndex(\"focus\") then SetRaidTarget(\"focus\",4)", icon = 134400, desc = "An essential macro for serious Mythic+. Sets your mouseover to be your focus target and marks it with a Green marker (unless it's already marked with something else), letting you kick it with the macros below. end" },
                { name = "\"Auto Kick/Stun\" Macro — Counter Shot", body = "#showtooltip Counter Shot\n/cast [@focus,exists,nodead,harm] Counter Shot\n/stopmacro [@focus,exists,nodead,harm]\n/focus target\n/cleartarget\n/targetenemy\n/cast Counter Shot\n/target focus\n/clearfocus\n/startattack", icon = 134400, desc = "This Macro will automatically use your Kick on a random, casting target with no need for targeting or mouseover or focus. I like it for lower/uncoordinated keys. See a cast? Hit the macro. The third macro does the same concept but for Intimidation . Note that it will prefer kicking your focus if you have one. If you want it to prefer your mouseover, just swap out \"focus\" with \"mouseover\"." },
                { name = "\"Auto Kick/Stun\" Macro — Muzzle", body = "#showtooltip Muzzle\n/cast [@focus,exists,nodead,harm] Muzzle\n/stopmacro [@focus,exists,nodead,harm]\n/focus target\n/cleartarget\n/targetenemy\n/cast Muzzle\n/target focus\n/clearfocus\n/startattack", icon = 134400, desc = "This Macro will automatically use your Kick on a random, casting target with no need for targeting or mouseover or focus. I like it for lower/uncoordinated keys. See a cast? Hit the macro. The third macro does the same concept but for Intimidation . Note that it will prefer kicking your focus if you have one. If you want it to prefer your mouseover, just swap out \"focus\" with \"mouseover\"." },
                { name = "\"Auto Kick/Stun\" Macro — Intimidation", body = "#showtooltip\n/cast [@focus,exists,nodead,harm] Intimidation\n/stopmacro [@focus,exists,nodead,harm]\n/focus target\n/cleartarget\n/targetenemy\n/cast Intimidation\n/target focus\n/clearfocus\n/startattack", icon = 134400, desc = "This Macro will automatically use your Kick on a random, casting target with no need for targeting or mouseover or focus. I like it for lower/uncoordinated keys. See a cast? Hit the macro. The third macro does the same concept but for Intimidation . Note that it will prefer kicking your focus if you have one. If you want it to prefer your mouseover, just swap out \"focus\" with \"mouseover\"." },
                { name = "Disengage", body = "#showtooltip Disengage\n/stopcasting [nochanneling:rapid fire]\n/stopcasting [nochanneling:rapid fire]\n/use Disengage", icon = 134400, desc = "StopCasting Macro This macro will stop casts like Steady Shot and force a Disengage , but it will not cancel casts like Rapid Fire that you can actually Disengage in the middle of." },
                { name = "Cursor Macros for Ground-Targeted Abilities — Freezing Trap", body = "#showtooltip\n/use [@cursor]Freezing Trap", icon = 134400, desc = "These macros skip the green target circle placement step of using ground-targeted abilities. I use it for everything from Flare to Traps to Binding Shot to Volley and Flamefang Pitch (SV Midnight Ability). Just place your cursor where you want it to go." },
                { name = "Cursor Macros for Ground-Targeted Abilities — Tar Trap", body = "#showtooltip\n/use [@cursor]Tar Trap", icon = 134400, desc = "These macros skip the green target circle placement step of using ground-targeted abilities. I use it for everything from Flare to Traps to Binding Shot to Volley and Flamefang Pitch (SV Midnight Ability). Just place your cursor where you want it to go." },
                { name = "Cursor Macros for Ground-Targeted Abilities — Binding Shot", body = "#showtooltip\n/use [@cursor]Binding Shot", icon = 134400, desc = "These macros skip the green target circle placement step of using ground-targeted abilities. I use it for everything from Flare to Traps to Binding Shot to Volley and Flamefang Pitch (SV Midnight Ability). Just place your cursor where you want it to go." },
                { name = "Cursor Macros for Ground-Targeted Abilities — Volley", body = "#showtooltip\n/use [@cursor]Volley", icon = 134400, desc = "These macros skip the green target circle placement step of using ground-targeted abilities. I use it for everything from Flare to Traps to Binding Shot to Volley and Flamefang Pitch (SV Midnight Ability). Just place your cursor where you want it to go." },
                { name = "Cursor Macros for Ground-Targeted Abilities — Flamefang Pitch", body = "#showtooltip\n/use [@cursor]Flamefang Pitch", icon = 134400, desc = "These macros skip the green target circle placement step of using ground-targeted abilities. I use it for everything from Flare to Traps to Binding Shot to Volley and Flamefang Pitch (SV Midnight Ability). Just place your cursor where you want it to go." },
                { name = "Cursor Macros for Ground-Targeted Abilities — Flare", body = "#showtooltip\n/use [@cursor]Flare", icon = 134400, desc = "These macros skip the green target circle placement step of using ground-targeted abilities. I use it for everything from Flare to Traps to Binding Shot to Volley and Flamefang Pitch (SV Midnight Ability). Just place your cursor where you want it to go." },
                { name = "Pet \"Reset\" Macro", body = "/petpassive\n/petfollow\n/use Dash", icon = 134400, desc = "This macro is useful when jumping off ledges where you really want your pet to follow you. Petpassive and Petfollow can make the pet \"snap\" to you more readily. The Dash line ensures your pet gets back to you as quickly as possible." },
                { name = "Pet Taunt Macro", body = "#showtooltip\n/use [@mouseover,exists,harm][@focus,exists,harm]Growl\n/use Scale Shield\n/use Harden Carapace\n/use Bristle\n/use Bulwark\n/use Obsidian Skin\n/use Defense Matrix\n/use Solid Shell\n/use Shell Shield", icon = 134400, desc = "In Mythic+ it is sometimes useful to taunt powerful mobs right before their tank busters which can help save your tank's life. You'll wanna use a Beetle, Boar, Carapid (BM only), Core Hound (BM only), Mechanical, Scalehide, Shale Beast (BM only), or Turtle for this as they have a 50% DR on a 1-min CD." },
                { name = "Mouseover Tranq Shot", body = "#showtooltip\n/use [@mouseover,exists,harm,nodead][]Tranquilizing Shot", icon = 134400, desc = "Simply Tranqs your mouseover enemy, or your target if there is no valid mouseover." },
                { name = "Aspect of the Turtle", body = "#showtooltip Aspect of the Turtle\n/stopcasting\n/stopcasting\n/use Aspect of the Turtle\n/cancelaura Aspect of the Turtle", icon = 134400, desc = "Cancelaura Macro The default game lets you cancel Turtle by pressing it again but there is a \"grace\" period built into this. This macro skips the grace period and lets you activate and then cancel Turtle immediately. Do NOT use this if you're the kind of person who spams Turtle, this macro requires you to be deliberate with a single key press to activate/deactivate!" },
                { name = "Mouseover", body = "#showtooltip Multi-Shot\n/stopmacro [channeling:Rapid Fire]\n/use [@mouseover,exists,harm,nodead][]Multi-Shot\n/petattack\n/petassist", icon = 134400, desc = "Multi-Shot Mainly useful for Marksmanship which may want to Multi-Shot something separate from its main target just to activate Trick Shots , but also works fine for Beast Mastery, so I recommend using it for both." },
                { name = "Barbed Shot Mouseover for Multidotting", body = "#showtooltip\n/petassist\n/use [@mouseover,harm,nodead][]Barbed Shot", icon = 134400, desc = "Multidotting Barbed Shot on AoE is essential. This macro prefers your mouseover target, or your target if there isn't one." },
                { name = "Bestial Wrath Cancelaura Shroud Macro — Bestial Wrath", body = "#showtooltip\n/cancelaura Shroud of Concealment\n/cancelaura Camouflage\n/use Bestial Wrath", icon = 134400, desc = "If you open with Bestial Wrath from Camouflage Shroud of Concealment in Pack Leader, it can glitch out your Howl of the Pack Leader and prevent them from spawning, massively hindering your DPS. This macro ensures it cannot happen." },
                { name = "Black Arrow Cancelaura Shroud Macro + Mouseover", body = "#showtooltip Black Arrow\n/cancelaura Shroud of Concealment\n/cancelaura Camouflage\n/stopmacro [channeling:Rapid Fire]\n/use [@mouseover,exists,harm][]Black Arrow", icon = 134400, desc = "The same can happen with Black Arrow and Deathblow procs. In addition, this macro prefers our mouseover enemy for Black Arrow s. There are many scenarios where you can Black Arrow a secondary target but not your main target and this macro is essential for that. It is also sometimes optimal to Black Arrow something other than your current target due to positional constraints, like if your main target is a prio target but is currently out of AoE position. The nochanneling element is an MM addition that just prevents this cast from cancelling Rapid Fire ." },
                { name = "Auto Pet-Summon Kill Command Macro", body = "#showtooltip Kill Command\n/petassist\n/petattack\n/cast [@pet,dead] Revive Pet;\n/cast [@pet,noexists,mod:shift] Revive Pet;\n/cast [@pet,noexists] Call Pet 1;\n/cast Kill Command", icon = 134400, desc = "This macro will summon/ress your pet if you do not have one summoned, and is otherwise just a regular Kill Command macro. Set the Call Pet X number to whatever pet you default to. When I am Lusting in a group, I go in and change the macro to my Lust pet's number so that if I die in the key and hit KC, it will summon the right pet. Takes the thinking out of it. Note that the ress part is not 100% reliable if you pet unit is not actually present which can happen if you try to ress and then cancel the cast. So, you should still have Revive Pet bound separately. 2. Best Addons for Beast Mastery Hunter in The War Within" },
            },
