                { name = "Cursor Macros for Ground-Targeted Abilities — Flare", body = "#showtooltip\n/use [@cursor]Flare", icon = 134400, desc = "These macros skip the green target circle placement step of using ground-targeted abilities. I use it for everything from Flare to Traps to Binding Shot to Volley and Flamefang Pitch (SV Midnight Ability). Just place your cursor where you want it to go." },
                { name = "Pet \"Reset\" Macro", body = "/petpassive\n/petfollow\n/use Dash", icon = 134400, desc = "This macro is useful when jumping off ledges where you really want your pet to follow you. Petpassive and Petfollow can make the pet \"snap\" to you more readily. The Dash line ensures your pet gets back to you as quickly as possible." },
                { name = "Pet Taunt Macro", body = "#showtooltip\n/use [@mouseover,exists,harm][@focus,exists,harm]Growl\n/use Scale Shield\n/use Harden Carapace\n/use Bristle\n/use Bulwark\n/use Obsidian Skin\n/use Defense Matrix\n/use Solid Shell\n/use Shell Shield", icon = 134400, desc = "In Mythic+ it is sometimes useful to taunt powerful mobs right before their tank busters which can help save your tank's life. You'll wanna use a Beetle, Boar, Carapid (BM only), Core Hound (BM only), Mechanical, Scalehide, Shale Beast (BM only), or Turtle for this as they have a 50% DR on a 1-min CD." },
                { name = "Mouseover Tranq Shot", body = "#showtooltip\n/use [@mouseover,exists,harm,nodead][]Tranquilizing Shot", icon = 134400, desc = "Simply Tranqs your mouseover enemy, or your target if there is no valid mouseover." },
                { name = "Aspect of the Turtle", body = "#showtooltip Aspect of the Turtle\n/stopcasting\n/stopcasting\n/use Aspect of the Turtle\n/cancelaura Aspect of the Turtle", icon = 134400, desc = "Cancelaura Macro The default game lets you cancel Turtle by pressing it again but there is a \"grace\" period built into this. This macro skips the grace period and lets you activate and then cancel Turtle immediately. Do NOT use this if you're the kind of person who spams Turtle, this macro requires you to be deliberate with a single key press to activate/deactivate!" },
                { name = "Mouseover", body = "#showtooltip Multi-Shot\n/stopmacro [channeling:Rapid Fire]\n/use [@mouseover,exists,harm,nodead][]Multi-Shot\n/petattack\n/petassist", icon = 134400, desc = "Multi-Shot Mainly useful for Marksmanship which may want to Multi-Shot something separate from its main target just to activate Trick Shots , but also works fine for Beast Mastery, so I recommend using it for both." },
                { name = "Auto Pet-Summon Kill Command Macro", body = "#showtooltip Kill Command\n/petassist\n/petattack\n/cast [@pet,dead] Revive Pet;\n/cast [@pet,noexists,mod:shift] Revive Pet;\n/cast [@pet,noexists] Call Pet 1;\n/cast Kill Command", icon = 134400, desc = "This macro will summon/ress your pet if you do not have one summoned, and is otherwise just a regular Kill Command macro. Set the Call Pet X number to whatever pet you default to. When I am Lusting in a group, I go in and change the macro to my Lust pet's number so that if I die in the key and hit KC, it will summon the right pet. Takes the thinking out of it. Note that the ress part is not 100% reliable if you pet unit is not actually present which can happen if you try to ress and then cancel the cast. So, you should still have Revive Pet bound separately." },
                { name = "Wildfire Bomb Mouseover Macro", body = "#showtooltip Wildfire Bomb\n/petattack\n/use [@mouseover,harm,nodead,exists][]Wildfire Bomb", icon = 134400, desc = "Wildfire Bomb is both a cone behind your target and a circle around it, but in spread AoE situations you may have to rely entirely on the cone and mouseover Bombing is extremely potent here to ensure maximum coverage." },
                { name = "Harpoon Mouseover Macro", body = "#showtooltip\n/use [@mouseover,exists,harm][]harpoon\n/cancelaura Updraft", icon = 134400, desc = "For quick position changes to a particular target without necessarily changing your DPS target. Also just feels cool af. 2. Best Addons for Survival Hunter in The War Within" },
