            Subtlety = {
                { name = "Shadow Dance Macros — Secret Technique", body = "#showtooltip Shadow Dance\n/cast Shadow Dance\n/cast Secret Technique", icon = 134400, desc = "At certain haste haste thresholds it can be very tight to fit in all of your spells into Shadow Dance due to Deepening Shadows . For example if the duration of Shadow Dance is 7.2 seconds you only have 0.2 seconds of leeway for your last spell, which is why using a macro like this is very useful to minimize any delay from needing to press multiple different buttons at the same time. Unfortunately due to a bug it is impossible to include Shadowstrike in a macro like this, so these are only useful if you are entering Shadow Dance with a full combo point bar." },
