    PRIEST = {
        pve = {
            Shadow = {
                { name = "Angelic Feather", body = "#showtooltip\n/cast [@player] Angelic Feather", icon = 134400, desc = "This is a simple macro that will always cast Angelic Feather at your feet." },
                { name = "Angelic Feather — Angelic Feather", body = "#showtooltip\n/cast [known:121536,mod:shift,@player] Angelic Feather; Power Word: Shield", icon = 134400, desc = "+ Body and Soul This macro simply combines Angelic Feather and Power Word: Shield with one macro, so you can easily use both with mostly the same keybind. This has default press Power Word: Shield, or pressing the same keybind with Shift casts Angelic Feather. reset=6 Power Word: Shield, Angelic Feather, Angelic Feather, Angelic Feather; Power Word: Shield This is another version of a movement macro that lets you spam the button over and over to cast the right movement spell, starting with Power Word: Shield . If you are looking for something simpler and do not want a mod:shift one, you can try this one out instead." },
                { name = "Angelic Feather — Variant 1", body = "#showtooltip\n/castsequence [known:121536,@mouseover,help,nodead][known:121536,@player]", icon = 134400, desc = "+ Body and Soul This macro simply combines Angelic Feather and Power Word: Shield with one macro, so you can easily use both with mostly the same keybind. This has default press Power Word: Shield, or pressing the same keybind with Shift casts Angelic Feather. reset=6 Power Word: Shield, Angelic Feather, Angelic Feather, Angelic Feather; Power Word: Shield This is another version of a movement macro that lets you spam the button over and over to cast the right movement spell, starting with Power Word: Shield . If you are looking for something simpler and do not want a mod:shift one, you can try this one out instead." },
                { name = "Power Infusion", body = "#showtooltip\n/cast [@INSERTPLAYERNAMEHERE,help,nodead][] Power Infusion\n/cast [@player] Power Infusion", icon = 134400, desc = "When using Twins of the Sun Priestess , this is a useful macro to cast Power Infusion on an ally to make sure your group gets the most out of it. You will need to manually type in the player you wish to give Power Infusion to, but it should handle if the target is out of range of you to still cast it on yourself. If you want to cast it on different players throughout an encounter I would suggest replacing @INSERTPLAYERNAMEHERE with @mouseover and mousing over the target you want to give it on for each cast. If you are having issues with this sometimes not working correctly, you should try to avoid spamming the macro when you want to cast it. If you queue the macro as an action mid-cast of something else, it can short-circuit." },
                { name = "Advanced — Variant 1", body = "/run local n=UnitName(\"target\") or \"player\" if not InCombatLockdown() then EditMacro(GetMacroIndexByName(\"PI\"),nil,nil,\"#showtooltip\\n/use 13\\n/cast [@mouseover,help,nodead][@\"..n..\",exists,nodead][] Power Infusion\") print(\"PI Updated to \"..n) end", icon = 134400, desc = "Power Infusion Macro If you find yourself editing the macro often to swap who you are giving Power Infusion to, you can use the below combination of macros to make this easier. The first macro requires you to target the player you want to give Power Infusion to. When clicking the macro, it will then update the second macro with the name of the target, so you do not need to manually type it in. The second macro will be automatically edited and overwritten when clicking the first macro. If you want to change anything in this macro, you must change it in the first one. You MUST name this second macro PI in order for it to work properly. This macro will be the one you actually end up binding to your bars and pressing. It will cast Power Infusion on your mouseover if it exists and is alive, then the Player you selected with the first macro, and finally yourself if the first two conditions failed. It will also use your trinket in the top slot, if you want to use the trinket in the bottom slot instead, change it from 13 to 14 on the last line." },
                { name = "Advanced — Power Infusion", body = "#showtooltip\n/use 13\n/cast [@mouseover,help,nodead][@PLAYERNAME] Power Infusion\n/cast Power Infusion", icon = 134400, desc = "Power Infusion Macro If you find yourself editing the macro often to swap who you are giving Power Infusion to, you can use the below combination of macros to make this easier. The first macro requires you to target the player you want to give Power Infusion to. When clicking the macro, it will then update the second macro with the name of the target, so you do not need to manually type it in. The second macro will be automatically edited and overwritten when clicking the first macro. If you want to change anything in this macro, you must change it in the first one. You MUST name this second macro PI in order for it to work properly. This macro will be the one you actually end up binding to your bars and pressing. It will cast Power Infusion on your mouseover if it exists and is alive, then the Player you selected with the first macro, and finally yourself if the first two conditions failed. It will also use your trinket in the top slot, if you want to use the trinket in the bottom slot instead, change it from 13 to 14 on the last line." },
                { name = "All in one Dispel Macro — Mass Dispel", body = "#showtooltip\n/cast [mod:alt,known:32375] !Mass Dispel; [@mouseover,help,nodead] Purify Disease; [@mouseover,harm,nodead] [harm] Dispel Magic; Purify Disease", icon = 134400, desc = "This gives you one button in-game that handles all of your dispel needs across the Priest specs. Alt is used for Mass Dispel ; if the target is an enemy, it uses Dispel Magic , and the default case is either Purify Disease or Purify . If you are just looking for a simple mouseover for one of these, you can use this instead: Simple Mass Dispel Cursor Macro:" },
                { name = "All in one Dispel Macro — Purify Disease", body = "#showtooltip\n/cast [@mouseover,help,nodead][] Purify Disease", icon = 134400, desc = "This gives you one button in-game that handles all of your dispel needs across the Priest specs. Alt is used for Mass Dispel ; if the target is an enemy, it uses Dispel Magic , and the default case is either Purify Disease or Purify . If you are just looking for a simple mouseover for one of these, you can use this instead: Simple Mass Dispel Cursor Macro:" },
                { name = "All in one Dispel Macro — Mass Dispel (2)", body = "#showtooltip\n/cast [@cursor] Mass Dispel", icon = 134400, desc = "This gives you one button in-game that handles all of your dispel needs across the Priest specs. Alt is used for Mass Dispel ; if the target is an enemy, it uses Dispel Magic , and the default case is either Purify Disease or Purify . If you are just looking for a simple mouseover for one of these, you can use this instead: Simple Mass Dispel Cursor Macro:" },
                { name = "Shackle Horror", body = "#showtooltip\n/cast [@mouseover,harm,nodead][] Shackle Horror", icon = 134400, desc = "Macro This is a simple mouseover macro for Shackle Horror that can be useful in certain Mythic+ situations." },
                { name = "Mind Control", body = "#showtooltip\n/petdismiss\n/cast [known:Mind Control] Mind Control; Dominate Mind", icon = 134400, desc = "Macro This macro offers a one-button solution for either Mind Control or Dominate Mind . Clicking it without an active pet will cast either spell on your current target. If you have an active pet Mind Controlled, it will instead dismiss it." },
                { name = "No-Cancel Stop Casting", body = "#showtooltip\n/stopmacro [channeling:Void Torrent]\n/cast Mind Blast", icon = 134400, desc = "If you find yourself spamming your buttons too quickly and cancelling important spells like Void Torrent you can adjust your spells like so. With these kinds of macros, it will only cast Mind Blast if you are not channeling Void Torrent . This can be useful if you like to spam your buttons." },
                { name = "Silence", body = "#showtooltip Silence\n/cast [@focus,harm,nodead][] Silence", icon = 134400, desc = "This is a basic macro I would suggest to anyone playing a spec with a kick. It prioritizes kicking your focus target and then defaults to your current target if you do not have a focus. You can also add mod:shift as an extra conditional if you only want to kick your focus target with a keybind used." },
                { name = "Mind Flay", body = "/console cameraSmoothTrackingStyle 0", icon = 134400, desc = "Camera Spin This is not a macro but a console command that will prevent Mind Flay from spinning your camera when it channels. This can be very helpful for players who find the camera interference annoying." },
                { name = "Mouseover Macro for DoTs — Shadow Word: Pain", body = "#showtooltip\n/cast [@mouseover,harm,nodead] [] Shadow Word: Pain", icon = 134400, desc = "These macros cast Shadow Word: Pain and Vampiric Touch at your current mouseover target without having to target their nameplate directly. This is particularly useful in multi-DoT situations in council boss scenarios. 2. Best Addons for Shadow Priest in The War Within With the changes in Midnight there will be lots of new addons to try out and experiment with. Over time I will add my favorites into this section if you want to mimic what I have done as a starting point." },
                { name = "Mouseover Macro for DoTs — Vampiric Touch", body = "#showtooltip\n/cast [@mouseover,harm,nodead] [] Vampiric Touch", icon = 134400, desc = "These macros cast Shadow Word: Pain and Vampiric Touch at your current mouseover target without having to target their nameplate directly. This is particularly useful in multi-DoT situations in council boss scenarios. 2. Best Addons for Shadow Priest in The War Within With the changes in Midnight there will be lots of new addons to try out and experiment with. Over time I will add my favorites into this section if you want to mimic what I have done as a starting point." },
            },
        },
        pvp = {
            Discipline = {
                { name = "Shadow Word: Death Macro", body = "#showtooltip Shadow Word: Death\n/stopcasting\n/cast [@target,harm] Shadow Word: Death\n/stopmacro [harm]\n/targetenemy\n/cast Shadow Word: Death\n/targetlasttarget [harm]", icon = 134400, desc = "This macro allows you to use Shadow Word: Death both to avoid incoming crowd control and to deal damage with only one keybind. If you target an enemy, the macro will simply use Shadow Word: Death on the enemy. This is what you want to deal damage and also to avoid CC. And if you target an ally the macro will target a nearby enemy to use the ability on. That way you can quickly press this macro when healing an ally if you notice a spell such as Polymorph being cast on you, and you will death it." },
                { name = "Power Word: Barrier Macro", body = "#showtooltip Power Word: Barrier\n/cast [@cursor] Power Word: Barrier", icon = 134400, desc = "This macro allows you to drop your Power Word: Barrier on your cursor location without having to click it, allowing you to be faster. Make sure you are well aware of the range and radius of your spell before you stat using this macro." },
                { name = "Purify Macro", body = "#showtooltip Purify\n/cast [target=party1] Purify", icon = 134400, desc = "This macro allows you to cast Purify on your party1 without having to target it, for a quicker dispel. You can reproduce this with party2 when you play 3v3 and have two people on your team." },
                { name = "Target Assist Macros", body = "#showtooltip Solace\n/cast [harm][@targettarget] Mind Blast", icon = 134400, desc = "This macro allows you to cast Mind Blast on the target of any ally you are targeting yourself without targeting the enemy. Such a macro allows you to keep doing your damage rotation without having to switch targets between your DPS and their kill target. You can reproduce this macro with Penance , Smite , and Shadow Word: Pain ." },
                { name = "Dispel Magic Macro", body = "#showtooltip Dispel Magic\n/cast [target=focus] Dispel Magic", icon = 134400, desc = "This macro allows you to cast Dispel Magic on your focus target without having to target it." },
                { name = "Mind Control Macro", body = "#showtooltip Mind Control\n/cast [target=focus] Mind Control", icon = 134400, desc = "This macro allows you to cast Mind Control on your focus target without having to target it." },
                { name = "Shackle Undead Macro", body = "#showtooltip Shackle Undead\n/cast [@arenapet1, exists] shackle undead\n/cast [@arenapet2, exists] shackle undead\n/cast [@arenapet3, exists] shackle undead", icon = 134400, desc = "This very handy macro allows you to cast Shackle Undead on the Undead pet of a Hunter without having to target it, regardless of whether the Hunter is Arena1, Arena2, or Arena3. You simply need to use it and if there is an Undead pet it will be controlled. This is helpful to easily deny Roar of Sacrifice when your team is about to do a go. Make sure to have a separate Shackle Undead keybind to crowd control a Death Knight who uses Lichborne . 8." },
            },
            Holy = {
                { name = "Holy Word: Chastise 123 Macro", body = "#showtooltip Holy Word: Chastise\n/cast [target=arena1] Holy Word: Chastise", icon = 134400, desc = "Using this macro will use Holy Word: Chastise on arena enemy 1. This makes it easier to crowd control an enemy while healing your team. If you want macros for the second and third enemies, simply change the arena1 to arena2 or arena3. You can reproduce this macro with Mind Control ." },
                { name = "Shadow Word: Death Macro", body = "#showtooltip Shadow Word: Death\n/stopcasting\n/cast [@target,harm] Shadow Word: Death\n/stopmacro [harm]\n/targetenemy\n/cast Shadow Word: Death\n/targetlasttarget [harm]", icon = 134400, desc = "This macro allows you to use Shadow Word: Death both to avoid incoming crowd control and to deal damage with only one keybind. If you target an enemy, the macro will simply use Shadow Word: Death on the enemy. This is what you want to deal damage and also to avoid CC. And if you target an ally the macro will target a nearby enemy to use the ability on. That way you can quickly press this macro when healing an ally if you notice a spell such as Polymorph being cast on you, and you will death it." },
                { name = "Shackle Undead Macro", body = "#showtooltip Shackle Undead\n/cast [@arenapet1, exists] shackle undead\n/cast [@arenapet2, exists] shackle undead\n/cast [@arenapet3, exists] shackle undead", icon = 134400, desc = "This very handy macro allows you to cast Shackle Undead on the Undead pet of a Hunter without having to target it, regardless of whether the Hunter is Arena1, Arena2, or Arena3. You simply need to use it and if there is an Undead pet it will be controlled. This is helpful to easily deny Roar of Sacrifice when your team is about to do a go. Make sure to have a separate Shackle Undead keybind to crowd control a Death Knight who uses Lichborne ." },
                { name = "Purify Party Macro", body = "#showtooltip Purify\n/cast [target=party1] Purify", icon = 134400, desc = "Using this macro will cast Purify on party player 1. This makes it easier to dispel a teammate while healing the rest of your team. If you want a macro to dispel the second party member, change the party1 to party2." },
                { name = "Dispel Magic Macro", body = "#showtooltip Dispel Magic\n/cast [target=focus] Dispel Magic", icon = 134400, desc = "This macro allows you to cast Dispel Magic on your focus target without having to target it." },
                { name = "Target Assist Macros", body = "#showtooltip Holy Fire\n/cast [harm][@targettarget] Holy Fire", icon = 134400, desc = "This macro allows you to cast Holy Fire on the target of any ally you are targeting yourself without targeting the enemy. Such a macro allows you to keep doing your damage rotation without having to switch targets between your DPS and their kill target. You can reproduce this macro with Smite ." },
                { name = "Holy Word: Sanctify Macro", body = "#showtooltip Holy Word: Sanctify\n/cast [@cursor] Holy Word: Sanctify", icon = 134400, desc = "This macro allows you to drop your Holy Word: Sanctify on your cursor location without having to click it, allowing you to be faster. Make sure you are well aware of the range and radius of your spell before you stat using this macro. 8." },
            },
            Shadow = {
                { name = "Silence 123 Macro", body = "#showtooltip Silence\n/cast [target=arena1] Silence", icon = 134400, desc = "Using this macro will cast Silence on arena enemy 1. This makes it easier to crowd control an enemy while staying focused on your target. If you want macros for the second and third enemies, simply change the arena1 to arena2 or arena3." },
                { name = "Silence Focus Macro", body = "#showtooltip Silence\n/cast [target=focus] Silence", icon = 134400, desc = "If you find that you do not have much room on your action bars, you can use a focus macro. This is much simpler to use than the arena123 macro. Put an enemy on focus and this macro will use Silence on that player while you are still focused on your target." },
                { name = "Leap of Faith Party Member Macro", body = "#showtooltip\n/cast [target=PUTNAMEHERE] Leap of Faith", icon = 134400, desc = "This macro will use Leap of Faith on whichever player you put in the macro. It is recommended that you make a macro for both of your arena partners." },
                { name = "Focus Dispel Magic", body = "#showtooltip\n/stopcasting\n/cast [@focus] Dispel Magic", icon = 134400, desc = "This macro will use Dispel Magic on the target you have set to Focus. This will make it easier to use without having to manually target who you want to Dispel Magic. 5." },
            },
        },
    },
    DEATHKNIGHT = {
        pve = {
            Blood = {
                { name = "Raise Ally", body = "#showtooltip Raise Ally\n/cast [@mouseover,help][@target]Raise Ally", icon = 134400, desc = "This macro casts Raise Ally on your mouseover target, if they are a friendly player. Otherwise, it casts Raise Ally on your current target." },
                { name = "Mind Freeze", body = "#showtooltip Mind Freeze\n/cast [@focus,harm,nodead][] Mind Freeze", icon = 134400, desc = "This macro allows you to interrupt your focus target, if you have one, and if not to simply interrupt your current target." },
                { name = "Gorefiend's Grasp", body = "#showtooltip Gorefiend's Grasp\n/cast [mod:shift,@focus,exists][@mouseover,exists,nodead][@player] Gorefiend's Grasp", icon = 134400, desc = "If you hover your cursor over a valid target to center Gorefiend's Grasp on, this macro will cast Gorefiend's Grasp at your cursor. By holding shift, it will instead cast Gorefiend's Grasp on your focus target. Otherwise, it will center your Gorefiend's Grasp on yourself." },
                { name = "Death and Decay", body = "#showtooltip Death and Decay\n/cleartarget\n/cast [@cursor] Death and Decay; [mod:ctrl, @player] Death and Decay\n/targetlasttarget", icon = 134400, desc = "This will drop Death and Decay where your cursor is at, skipping the entire targeting reticule in the process and saving you 200-500ms in the process. Holding down CTRL will instead drop it at your feet." },
                { name = "Blessing of Protection Cancelaura Macro", body = "/cancelaura Blessing of Protection", icon = 134400, desc = "This macro is very useful to have. It allows you to cancel a Blessing of Protection that may have been cast on you. It is important because while you are under the effect of Blessing of Protection, mobs will not attack you and instead will just attack the next person on the aggro list (often a DPS player), though taunting a mob will still force it to attack you for 3 seconds." },
                { name = "Re-Control Pet", body = "/target pet\n/run PetDismiss()\n/use Control Undead\n/petassist", icon = 134400, desc = "" },
            },
            Frost = {
                { name = "Raise Ally", body = "#showtooltip Raise Ally\n/cast [@mouseover,help][@target]Raise Ally", icon = 134400, desc = "This macro casts Raise Ally on your mouseover target, if they are a friendly player. Otherwise, it casts Raise Ally on your current target." },
                { name = "Mind Freeze", body = "#showtooltip Mind Freeze\n/cast [@focus,harm,nodead][] Mind Freeze", icon = 134400, desc = "This macro allows you to interrupt your focus target, if you have one, and if not to simply interrupt your current target." },
                { name = "Obliteration Trigger Macro — Raise Dead", body = "#showtooltip Pillar of Frost\n/use trinket\n/cast Pillar of Frost\n/cast Breath of Sindragosa\n/cast Reaper's Mark\n/cast Raise Dead", icon = 134400, desc = "Maximising the value of Obliteration means fully utilising all the available GCDs you have during the window. Since Pillar of Frost is off the GCD, we want to macro it with a GCD-button to start using your abilities ASAP in the window. When playing Deathbringer , you can use Pillar of Frost with Reaper's Mark to simplify you rotation. In AoE, it is recommend to use Reaper's Mark before pillar. Furthermore, you can add in Breath of Sindragosa in this macro to further cut down on the button requirement. For Rider of the Apocalypse , we end up in a more complicated situation as the on-GCD ability we use with our Pillar of Frost changes depending on situation. We have separate macros for Frost Strike , Glacial Advance , Obliterate , Frostscythe and Howling Blast . Choosing what macro you press is exactly like following your standard priority (Frost Strike with Frostbane, Obliterate with Killing Machine in Single Target etc). If you want to fully optimise each one of your standard abilities has a pillar macro version as well with the following structure: The exact macros to use are the written out below. Important to note, you also use the Frostscythe macro and Obliterate macro with Deathbringer when you do the early Reaper's Mark tech." },
