                { name = "Obliteration Trigger Macro — Howling Blast", body = "#showtooltip Pillar of Frost\n/use trinket\n/cast Pillar of Frost\n/cast Raise Dead\n/cast Howling Blast", icon = 134400, desc = "Maximising the value of Obliteration means fully utilising all the available GCDs you have during the window. Since Pillar of Frost is off the GCD, we want to macro it with a GCD-button to start using your abilities ASAP in the window. When playing Deathbringer , you can use Pillar of Frost with Reaper's Mark to simplify you rotation. In AoE, it is recommend to use Reaper's Mark before pillar. Furthermore, you can add in Breath of Sindragosa in this macro to further cut down on the button requirement. For Rider of the Apocalypse , we end up in a more complicated situation as the on-GCD ability we use with our Pillar of Frost changes depending on situation. We have separate macros for Frost Strike , Glacial Advance , Obliterate , Frostscythe and Howling Blast . Choosing what macro you press is exactly like following your standard priority (Frost Strike with Frostbane, Obliterate with Killing Machine in Single Target etc). If you want to fully optimise each one of your standard abilities has a pillar macro version as well with the following structure: The exact macros to use are the written out below. Important to note, you also use the Frostscythe macro and Obliterate macro with Deathbringer when you do the early Reaper's Mark tech." },
                { name = "Death Grip Mouseover Macro", body = "#showtooltip Death Grip\n/cast [target=mouseover,exists] Death Grip; Death Grip", icon = 134400, desc = "This macro will cast Death Grip on your mouseover target." },
                { name = "Anti-Magic Zone Cursor", body = "#showtooltip Anti-Magic Zone\n/cast [@cursor] Anti-Magic Zone", icon = 134400, desc = "This macro instantly casts Anti-Magic Zone at your cursor's location. It is useful for activating the Zone a tiny bit more quickly by spamming this macro button. It also generally helps in placing it effectively." },
                { name = "Control Undead", body = "#showtooltip Control Undead\n/target pet\n/script PetDismiss()\n/cast Control Undead", icon = 134400, desc = "Controlling an Undead creature in dungeons is a nice way to add some minor extra damage, as well as control a specific mob for however long you want. It does need re-controlling every 5 minutes, and this macro is perfect for that! It will target your pet, dismiss it, and then instantly control it again." },
            },
            Unholy = {
                { name = "Raise Ally", body = "#showtooltip Raise Ally\n/cast [@mouseover,help][@target]Raise Ally", icon = 134400, desc = "This macro casts Raise Ally on your mouseover target, if they are a friendly player. Otherwise, it casts Raise Ally on your current target." },
                { name = "Mind Freeze", body = "#showtooltip Mind Freeze\n/cast [@focus,harm,nodead][] Mind Freeze", icon = 134400, desc = "This macro allows you to interrupt your focus target, if you have one, and if not to simply interrupt your current target." },
                { name = "Outbreak Mouseover Macro", body = "#showtooltip Outbreak\n/cast [target=mouseover,exists] Outbreak; Outbreak", icon = 134400, desc = "This macro will cast Outbreak on your mouseover target." },
                { name = "Dismissing Pet", body = "/petdismiss", icon = 134400, desc = "This macro allows you to dismiss your pet, which might be required for dungeons, especially if you also have All Will Serve talent that can easily ninja pull." },
                { name = "@Cursor Macros — Death and Decay", body = "#showtooltip Death and Decay\n/cast [@cursor] Death and Decay", icon = 134400, desc = "These macros allow you to quickly plant your Death and Decay Defile or Anti-Magic Zone on your cursor." },
                { name = "@Cursor Macros — Anti-Magic Zone", body = "#showtooltip Anti-Magic Zone\n/cast [@cursor] Anti-Magic Zone", icon = 134400, desc = "These macros allow you to quickly plant your Death and Decay Defile or Anti-Magic Zone on your cursor." },
                { name = "Pet Macros — Variant 1", body = "/petmoveto", icon = 134400, desc = "Controlling your pet is a great way of optimizing your DPS and gameplay, here are some useful macros for that! Move your pet to where you want. Make it follow you so it does not get stuck somewhere! Resummoning the pet is sometimes the last resort to get it to you. This macro will dismiss your pet if you have it and raise it if you do not. Be careful to spam this as it can accidentally dismiss your pet twice, leaving you waiting for 30 seconds before you can summon it again." },
                { name = "Pet Macros — Variant 2", body = "/petfollow", icon = 134400, desc = "Controlling your pet is a great way of optimizing your DPS and gameplay, here are some useful macros for that! Move your pet to where you want. Make it follow you so it does not get stuck somewhere! Resummoning the pet is sometimes the last resort to get it to you. This macro will dismiss your pet if you have it and raise it if you do not. Be careful to spam this as it can accidentally dismiss your pet twice, leaving you waiting for 30 seconds before you can summon it again." },
                { name = "Pet Macros — Raise Dead", body = "/script PetDismiss()\n/cast [nopet] Raise Dead", icon = 134400, desc = "Controlling your pet is a great way of optimizing your DPS and gameplay, here are some useful macros for that! Move your pet to where you want. Make it follow you so it does not get stuck somewhere! Resummoning the pet is sometimes the last resort to get it to you. This macro will dismiss your pet if you have it and raise it if you do not. Be careful to spam this as it can accidentally dismiss your pet twice, leaving you waiting for 30 seconds before you can summon it again." },
                { name = "Control Undead", body = "#showtooltip Control Undead\n/target pet\n/script PetDismiss()\n/cast Control Undead", icon = 134400, desc = "Controlling an Undead creature in dungeons is generally a major DPS downgrade for Unholy. However, it is sometimes needed for hard CC. The macro below automatically dismisses the controlled pet and then controls it straight afterward:" },
            },
