                { name = "Purge", body = "#showtooltip\n/stopcasting\n/cast [@focus,exists][@target] Purge", icon = 134400, desc = "This macro will stop your current cast and cast Purge on your focus if available, otherwise it will be cast on your target." },
                { name = "Wind Rush Totem — Wind Rush Totem", body = "#showtooltip\n/stopcasting\n/cast [@player] Wind Rush Totem", icon = 134400, desc = "Two options are available, allowing you to either instantly cast Wind Rush Totem at your feet: Or at your current cursor location: These remove an input and allow you to activate the totem much quicker than usual to get the movement speed rolling quickly." },
