                { name = "Ancestral Swiftness macro for", body = "#showtooltip Lava Burst\n/use Ancestral Swiftness\n/cast Lava Burst", icon = 134400, desc = "Farseer In order to maintain maximum uptime and keep the ability as easy to use as possible, we recommend macroing Ancestral Swiftness to at least Lava Burst in order to maximize uptime without having to think about it. Replace your Lava Burst bind with this macro, you can also do the same with Lightning Bolt and Chain Lightning :" },
                { name = "Maintenance buff Castsequence Macro", body = "#showtooltip\n/castsequence reset=10 Skyfury, Lightning Shield", icon = 134400, desc = "This macro will cast your two maintenance buffs in sequence with one button. Thanks to Instinctive Imbuements you only need two GCDs to apply all your buffs, as applying Lightning Shield will apply Earth Shield , Flametongue Weapon and Thunderstrike Ward for free if talented. Note that you probably want a separate Earth Shield bind at least so you can put it on others and refresh it during a dungeon or in combat." },
                { name = "Totemic Projection Castsequence Macro", body = "#showtooltip\n/castsequence [@cursor] reset=20 Wind Rush Totem, Totemic Projection, Totemic Projection", icon = 134400, desc = "This casts Wind Rush Totem then Totemic Projection at your cursor. It can be adapted to be used with any totem." },
                { name = "Cursor/Mouseover Earthquake, Capacitor Totem & Flame Shock — Earthquake", body = "#showtooltip\n/cast [@cursor] Earthquake", icon = 134400, desc = "This casts Earthquake at your cursor's current location, eliminating the target reticle. Be careful with this macro, as it can easily lead to mistakes, but some players prefer the speed and convenience that it can provide. You can replace Earthquake with or Capacitor Totem. The following macro will cast Flame Shock on the target your cursor is on. If your cursor is not on any enemy, it will instead cast it on your selected target." },
                { name = "Cursor/Mouseover Earthquake, Capacitor Totem & Flame Shock — Flame Shock", body = "#showtooltip\n/cast [@mouseover,exists]Flame Shock;Flame Shock", icon = 134400, desc = "This casts Earthquake at your cursor's current location, eliminating the target reticle. Be careful with this macro, as it can easily lead to mistakes, but some players prefer the speed and convenience that it can provide. You can replace Earthquake with or Capacitor Totem. The following macro will cast Flame Shock on the target your cursor is on. If your cursor is not on any enemy, it will instead cast it on your selected target." },
                { name = "Spirit Walk", body = "#showtooltip\n/stopcasting\n/cast Spirit Walk\n/cast Spiritwalker's Grace", icon = 134400, desc = "+ Time Spiral Abuse Macro This macro takes advantage of the off-the-global-cooldown nature of Spirit Walk and Spiritwalker's Grace and allows us to \"double dip\" from Time Spiral by getting the benefit of both abilities." },
                { name = "Focus Target Macro", body = "/clearfocus [modifier:alt][@focus,dead][@focus,noexists]\n/focus [@focus,noexists]\n/cast [@focus] Wind Shear", icon = 134400, desc = "This designates a target as your focus and optionally immediately uses a spell at it. Generally used with Wind Shear or Hex , but works with most spells." },
                { name = "Primal Fire Elemental Meteor Macro — meteor", body = "#showtooltip\n/use [pet:primal fire elemental]meteor", icon = 134400, desc = "This macro allows you to manually cast your Primal Fire Elemental 's Meteor ability. Note that now that the Elemental can auto-cast this ability unless you specifically want to use them manually, this macro is not useful in most situations. Similar macros can be used when a talent choice between two active abilities is available. In Midnight, there are only 2 additional uses: Gust of Wind vs. Spirit Walk and Earth Shock vs. Elemental Blast . For example: This next macro allows you to cast Earth Shield on an ally on mouseover if the Elemental Orbit talent is used. If your cursor is not on an ally or the previous talent was not taken, it will cast Earth Shield on yourself." },
                { name = "Primal Fire Elemental Meteor Macro — gust of wind", body = "#showtooltip\n/use [known:gust of wind]gust of wind;[known:spirit walk]spirit walk", icon = 134400, desc = "This macro allows you to manually cast your Primal Fire Elemental 's Meteor ability. Note that now that the Elemental can auto-cast this ability unless you specifically want to use them manually, this macro is not useful in most situations. Similar macros can be used when a talent choice between two active abilities is available. In Midnight, there are only 2 additional uses: Gust of Wind vs. Spirit Walk and Earth Shock vs. Elemental Blast . For example: This next macro allows you to cast Earth Shield on an ally on mouseover if the Elemental Orbit talent is used. If your cursor is not on an ally or the previous talent was not taken, it will cast Earth Shield on yourself." },
                { name = "Primal Fire Elemental Meteor Macro — Earth Shield", body = "#showtooltip\n/use [@mouseover,help,nodead,known:383010]Earth Shield;[@player]Earth Shield", icon = 134400, desc = "This macro allows you to manually cast your Primal Fire Elemental 's Meteor ability. Note that now that the Elemental can auto-cast this ability unless you specifically want to use them manually, this macro is not useful in most situations. Similar macros can be used when a talent choice between two active abilities is available. In Midnight, there are only 2 additional uses: Gust of Wind vs. Spirit Walk and Earth Shock vs. Elemental Blast . For example: This next macro allows you to cast Earth Shield on an ally on mouseover if the Elemental Orbit talent is used. If your cursor is not on an ally or the previous talent was not taken, it will cast Earth Shield on yourself." },
                { name = "Goblin only! Gust of Wind and Rocket Jump Macro", body = "#showtooltip\n/castsequence reset=14 Gust of Wind, Rocket Jump", icon = 134400, desc = "Fellow goblins can also use a castsequence macro, making them use Rocket Jump when Gust of Wind is on cooldown. Note that the cooldown used for the reset needs to be low because of Flash of Lightning ." },
                { name = "Healing or Raising an Ally", body = "#showtooltip\n/use [@mouseover,help,dead]Ancestral Spirit;[@mouseover,help,nodead]Healing Surge;[dead]Ancestral Spirit;Healing Surge", icon = 134400, desc = "This macro mostly will raise your ally if they are dead or heal them if they are alive." },
                { name = "Friend or Foe Adaptive Macros — Purge", body = "#showtooltip\n/use [@mouseover,harm,nodead,known:purge]Purge;[@mouseover,harm,nodead,known:greater purge]", icon = 134400, desc = "The following macro will cast Purge , Greater Purge or Cleanse Spirit depending on whether you are targeting an enemy or an ally: Greater Purge;[@mouseover,help,nodead]Cleanse Spirit;[harm,known:purge]Purge;[harm,known:greater purge]Greater Purge;Cleanse Spirit The following macro will cast Chain Lightning or Chain Heal depending on whether you are targeting an enemy or an ally. You can choose to remove individual elements from this macro. If, for example, you never want Chain Heal to be cast on mouseover, remove: [@mouseover,help,nodead]Chain Heal;" },
